"""Bound relative shader register indices with block-local proofs."""
import argparse
from pathlib import Path
import sys
from apply_memory_patch import blob_hash

PATH = "crates/victory-shader/src/ir.rs"
EXPECTED = "0b8fd9c6d047c263928cffd5c17890d7db106208"
EDITS = [["pub fn build(code: &[u8], wave64: bool, vgprs: u16) -> Result<Program, ShaderError> {","/// Conservative upper bounds within a single machine basic block.\ntype RelativeBounds = std::collections::HashMap<usize, u32>;\n\nfn relative_move(name: &str) -> bool {\n    matches!(name, \"v_movrels_b32\" | \"v_movreld_b32\" | \"v_movrelsd_b32\"\n        | \"v_movrelsd_2_b32\" | \"v_swaprel_b32\")\n}\n\nfn scalar_immediate(op: &Operand) -> Option<u32> {\n    match *op {\n        Operand::Const(c @ 128..=192) => Some(u32::from(c) - 128),\n        Operand::Literal(x) => Some(x),\n        _ => None,\n    }\n}\n\nfn local_relative_bounds(\n    list: &[Instruction], leaders: &[usize], wave64: bool, lanes: u8, vgprs: u16,\n) -> RelativeBounds {\n    let mut bounds = RelativeBounds::new();\n    let mut limit = None;\n    for inst in list {\n        if leaders.binary_search(&inst.offset).is_ok() {\n            limit = None;\n        }\n        let Some(name) = inst.name() else {\n            limit = None;\n            continue;\n        };\n        let fields = inst.fields(wave64);\n        if relative_move(name) {\n            if let Some(hi) = limit {\n                bounds.insert(inst.offset, hi);\n            }\n        }\n        if name.contains(\"pc\") || name.contains(\"call\") || name.contains(\"trap\")\n            || name.starts_with(\"s_setreg\") {\n            limit = None;\n        }\n        let Ok(effect) = effects(inst, &fields, name, lanes, vgprs, None) else {\n            limit = None;\n            continue;\n        };\n        let Some((_, writes)) = effect else { continue };\n        if !writes.contains(&Reg::S(M0)) {\n            continue;\n        }\n        limit = match (&fields, name) {\n            (Fields::Sop { dst: Some(Operand::Scalar { code: M0, dwords: 1 }), src, .. },\n                \"s_mov_b32\") if src.len() == 1 => scalar_immediate(&src[0]),\n            (Fields::Sop { dst: Some(Operand::Scalar { code: M0, dwords: 1 }), src, .. },\n                \"s_and_b32\" | \"s_min_u32\") if src.len() == 2 => {\n                src.iter().filter_map(scalar_immediate).min()\n            }\n            _ => None,\n        }.filter(|&hi| hi < 256);\n    }\n    bounds\n}\n\npub fn build(code: &[u8], wave64: bool, vgprs: u16) -> Result<Program, ShaderError> {"],["    let parked = unspill(&mut list, &leaders, wave64, lanes, vgprs);","    let bounds = local_relative_bounds(&list, &leaders, wave64, lanes, vgprs);\n    let parked = unspill(&mut list, &leaders, wave64, lanes, vgprs, &bounds);"],["effects(&machine, &fields, name, lanes, vgprs)?","effects(&machine, &fields, name, lanes, vgprs, bounds.get(&machine.offset).copied())?"],["    vgprs: u16,\n) -> Vec<(usize, u8, u8)> {","    vgprs: u16,\n    bounds: &RelativeBounds,\n) -> Vec<(usize, u8, u8)> {"],["effects(inst, &fields, name, lanes, vgprs) else","effects(inst, &fields, name, lanes, vgprs, bounds.get(&inst.offset).copied()) else"],["let relative = name == \"v_movrels_b32\";","let relative = name == \"v_movrels_b32\" && !bounds.contains_key(&inst.offset);"],["    effects(&inst.machine, &inst.fields, inst.name(), lanes, p.vgprs)\n        .ok()\n        .flatten()\n        .map_or_else(Vec::new, |e| e.0)","    let mut reads = effects(&inst.machine, &inst.fields, inst.name(), lanes, p.vgprs, None)\n        .ok()\n        .flatten()\n        .map_or_else(Vec::new, |e| e.0);\n    if relative_move(inst.name()) {\n        reads.retain(|r| inst.read(*r).is_some());\n    }\n    reads"],["    vgprs: u16,\n) -> Result<Option<Effects>, ShaderError> {","    vgprs: u16,\n    relative_limit: Option<u32>,\n) -> Result<Option<Effects>, ShaderError> {"],["                    out.extend((u16::from(reg)..vgprs).map(|r| Reg::V(r as u8)));","                    let base = u16::from(reg);\n                    let end = relative_limit.map_or(vgprs, |hi| {\n                        u32::from(base).saturating_add(hi).saturating_add(1)\n                            .min(u32::from(vgprs)) as u16\n                    });\n                    out.extend((base..end).map(|r| Reg::V(r as u8)));"],["    #[test]\n    fn relative_vgpr_access_spans_up_to_the_vgpr_count() {","    #[test]\n    fn local_relative_index_bounds_are_conservative() {\n        let moves = [0x7E04_8501u32, 0x7E00_8704];\n        let run = |prefix: &[u32], between: &[u32]| {\n            let mut words = prefix.to_vec();\n            words.push(moves[0]);\n            words.extend_from_slice(between);\n            words.push(moves[1]);\n            words.push(S_ENDPGM);\n            let bytes: Vec<u8> = words.iter().flat_map(|w| w.to_le_bytes()).collect();\n            build(&bytes, false, 12).unwrap()\n        };\n        let written = |p: &Program| {\n            p.blocks.iter().flat_map(|b| &b.insts)\n                .find(|i| i.name() == \"v_movreld_b32\").unwrap()\n                .writes.iter().filter(|(r, _)| matches!(r, Reg::V(_))).count()\n        };\n        let read = |p: &Program| {\n            p.blocks.iter().flat_map(|b| &b.insts)\n                .find(|i| i.name() == \"v_movrels_b32\").unwrap()\n                .reads.iter().filter(|(r, _)| matches!(r, Reg::V(_))).count()\n        };\n        // A constant index of 1 limits both moves to two possible registers.\n        let bounded = run(&[0xBEFC_0381], &[]);\n        assert_eq!(written(&bounded), 2);\n        assert_eq!(read(&bounded), 3); // includes the old destination\n        let unknown = run(&[], &[]);\n        assert_eq!(written(&unknown), 10);\n        assert_eq!(read(&unknown), 9);\n        // A new unknown M0 value invalidates the proof.\n        let reset = run(&[0xBEFC_0381], &[0xBEFC_0300]);\n        assert_eq!(written(&reset), 2);\n        assert_eq!(read(&reset), 9);\n        // A basic block boundary also invalidates a local proof.\n        let branch = run(&[0xBEFC_0381], &[0xBF82_0000]);\n        assert_eq!(read(&branch), 9);\n        // AND with 3 bounds an otherwise unknown index by 3.\n        let masked = run(&[0x8000_0000 | (0x0e << 23) | (124 << 16) | (131 << 8)], &[]);\n        assert_eq!(written(&masked), 4);\n        assert_eq!(read(&masked), 5);\n    }\n\n    #[test]\n    fn relative_vgpr_access_spans_up_to_the_vgpr_count() {"],["            match name {\n                \"v_swap_b32\" => {","            match name {\n                \"v_dot4c_i32_i8\" => {\n                    // Unlike an inactive-lane preservation read, the old\n                    // destination is an input to the arithmetic itself.\n                    if let Some(d) = &v.dst {\n                        regs(d, &mut r)?;\n                    }\n                }\n                \"v_swap_b32\" => {"],["    #[test]\n    fn relative_vgpr_access_spans_up_to_the_vgpr_count() {","    #[test]\n    fn accumulating_dot_reads_its_destination_as_an_operand() {\n        let words = [(0x0d_u32 << 25) | (2 << 9) | 257, S_ENDPGM];\n        let code: Vec<u8> = words.iter().flat_map(|w| w.to_le_bytes()).collect();\n        let p = build(&code, false, 8).unwrap();\n        let inst = &p.blocks[0].insts[0];\n        assert_eq!(inst.name(), \"v_dot4c_i32_i8\");\n        assert!(operand_reads(&p, inst).contains(&Reg::V(0)));\n        assert!(inst.read(Reg::V(0)).is_some());\n    }\n\n    #[test]\n    fn relative_vgpr_access_spans_up_to_the_vgpr_count() {"],["        Fields::Smem {\n            data,\n            base,\n            soffset,\n            ..\n        } => match name {","        Fields::Smem {\n            data,\n            base,\n            soffset,\n            cache,\n            ..\n        } => match name {\n            _ if name.starts_with(\"s_buffer_atomic_\") => {\n                regs(base, &mut r)?;\n                regs(soffset, &mut r)?;\n                let data = data.as_ref().ok_or_else(unsupported)?;\n                regs(data, &mut r)?;\n                if cache.glc {\n                    let Operand::Scalar { code, dwords } = *data else {\n                        return Err(unsupported());\n                    };\n                    let width = if name.contains(\"cmpswap\") { dwords / 2 } else { dwords };\n                    regs(&Operand::Scalar { code, dwords: width }, &mut w)?;\n                }\n            }"]]

def transform(data):
    normal = data.replace(b"\r\n", b"\n")
    if blob_hash(normal) != EXPECTED:
        raise ValueError("Unexpected pinned IR source.")
    source = normal.decode("utf-8")
    for before, after in EDITS:
        if source.count(before) != 1:
            raise ValueError("Relative index anchor differs.")
        source = source.replace(before, after)
    result = source.encode("utf-8")
    return result.replace(b"\n", b"\r\n") if b"\r\n" in data else result

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    root = args.checkout.resolve()
    try:
        if not (root / ".git").exists():
            raise ValueError("Separate checkout required.")
        target = root / PATH
        if target.resolve() != target or not target.is_file():
            raise ValueError("Invalid source path.")
        result = transform(target.read_bytes())
        if args.apply:
            target.write_bytes(result)
        print("Relative index source checks passed.")
    except (OSError, ValueError):
        print("Relative index preparation failed.", file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
